-- EMERGENCY ROLLBACK 075 (production). Generated by docs/releases/production-075/gen-emergency-rollback.py.
-- Run ONLY with the owner's approval, in ONE transaction:
--   psql "<production connection>" -X -v ON_ERROR_STOP=1 --single-transaction -f docs/releases/production-075/emergency/rollback_075_with_history.sql
-- Order: newest first (084, 083, 082, 081, 080, 079, 078, 077, 076, 075, 074, 073). Keeps every business row; removes the 075 history row so the migration history
-- matches the schema again (the plain supabase/rollback file does not touch supabase_migrations).
set lock_timeout = '10s';
set statement_timeout = '5min';
do $guard$
begin
  if to_regprocedure('public.deployment_environment()') is not null then
    raise exception 'STOP: JewelryFlow SaaS demo database, not Goldia';
  end if;
  if not exists (select 1 from supabase_migrations.schema_migrations where version = '20260101000075') then
    raise exception 'STOP: migration 075 is not recorded — nothing to roll back';
  end if;
  if exists (select 1 from supabase_migrations.schema_migrations where version > '20260101000075') then
    raise exception 'STOP: a newer migration is recorded — roll that back first';
  end if;
end $guard$;

-- ===== supabase/rollback/20260101000075_rollback.sql =====
-- ROLLBACK of 075 — restores the exact 074 state: global customer_code uniqueness, the 038 rpc_create_customer_with_code,
-- the 023 rpc_get_factory_settings, the customers table privileges, no code guard trigger. Keeps every row.
-- Run in one transaction:
--   psql "<connection>" -v ON_ERROR_STOP=1 --single-transaction -f supabase/rollback/20260101000075_rollback.sql
-- WARNING: this re-opens F-STG-1 (one long code breaks customer creation for every organization) and F-STG-2.
-- It refuses (and changes nothing) when two organizations already use the same customer_code: global uniqueness
-- cannot be restored without renaming customers, which this rollback never does.

do $$
begin
  if exists (select customer_code from public.customers group by customer_code having count(*) > 1) then
    raise exception 'ROLLBACK 075 REFUSED: the same customer_code is used by more than one organization (created after 075); global uniqueness cannot be restored without renaming customers';
  end if;
end $$;

drop trigger if exists trg_goldia_guard_customer_code on public.customers;
drop function if exists public._goldia_guard_customer_code();

alter table public.customers drop constraint if exists customers_org_customer_code_key;
do $$
begin
  if not exists (select 1 from pg_constraint where conrelid = 'public.customers'::regclass and conname = 'customers_customer_code_key') then
    alter table public.customers add constraint customers_customer_code_key unique (customer_code);
  end if;
end $$;

grant all on table public.customers to anon, authenticated;

-- rpc_create_customer_with_code exactly as in 20260101000038_final_sales_mega_fix.sql
create or replace function public.rpc_create_customer_with_code(
  p_contact_name text,
  p_phone        text default null,
  p_company_name text default null,
  p_seller_id    uuid default null,
  p_notes        text default null
)
returns jsonb
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_caller_org   uuid := public.current_organization_id();
  v_clean_name   text := nullif(btrim(p_contact_name), '');
  v_next_seq     integer;
  v_cust_code    text;
  v_cust_id      uuid;
  v_seller_id    uuid := p_seller_id;
  v_existing_id  uuid;
begin
  if v_caller_org is null then
    raise exception 'Permission denied: User must belong to an active organization' using errcode = '42501';
  end if;

  if v_clean_name is null then
    raise exception 'Mijoz ismi kiritilishi shart';
  end if;

  -- Default seller to caller employee if not supplied
  if v_seller_id is null then
    select id into v_seller_id
    from public.employees
    where user_id = auth.uid() and organization_id = v_caller_org
    limit 1;
  end if;

  -- Duplicate check by name and seller
  select id into v_existing_id
  from public.customers
  where organization_id = v_caller_org
    and lower(contact_name) = lower(v_clean_name)
    and (v_seller_id is null or seller_id = v_seller_id)
  limit 1;

  if v_existing_id is not null then
    return jsonb_build_object(
      'status', 'existing',
      'customer_id', v_existing_id,
      'message', 'Ushbu nomdagi mijoz allaqachon mavjud'
    );
  end if;

  -- Generate sequential customer code (look across entire table to respect unique constraint)
  select coalesce(max(nullif(regexp_replace(customer_code, '\D', '', 'g'), '')::integer), 0) + 1
  into v_next_seq
  from public.customers;

  v_cust_code := 'CUST-' || lpad(v_next_seq::text, 4, '0');

  -- Loop to guarantee zero unique constraint collision
  while exists (select 1 from public.customers where customer_code = v_cust_code) loop
    v_next_seq := v_next_seq + 1;
    v_cust_code := 'CUST-' || lpad(v_next_seq::text, 4, '0');
  end loop;

  insert into public.customers (
    organization_id, customer_code, contact_name, phone, company_name, seller_id, notes
  ) values (
    v_caller_org, v_cust_code, v_clean_name, p_phone, p_company_name, v_seller_id, p_notes
  ) returning id into v_cust_id;

  return jsonb_build_object(
    'status', 'ok',
    'customer_id', v_cust_id,
    'customer_code', v_cust_code,
    'contact_name', v_clean_name,
    'phone', p_phone,
    'seller_id', v_seller_id
  );
end;
$$;

revoke all on function public.rpc_create_customer_with_code(text, text, text, uuid, text) from public, anon;
grant execute on function public.rpc_create_customer_with_code(text, text, text, uuid, text) to authenticated, service_role;

-- rpc_get_factory_settings exactly as in 20260101000023_factory_settings_persistence_and_qc_rework.sql
create or replace function public.rpc_get_factory_settings(
  p_organization_id uuid default null
)
returns jsonb
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_org_id      uuid := coalesce(p_organization_id, public.current_organization_id());
  v_org         public.organizations%rowtype;
  v_settings    public.organization_factory_settings%rowtype;
begin
  if v_org_id is null then
    -- Fallback to default Goldia organization
    select * into v_org from public.organizations where code = 'goldia' limit 1;
    if found then
      v_org_id := v_org.id;
    end if;
  else
    select * into v_org from public.organizations where id = v_org_id;
  end if;

  select * into v_settings from public.organization_factory_settings where organization_id = v_org_id;

  if not found then
    -- Insert default settings row if missing
    insert into public.organization_factory_settings (
      organization_id,
      disabled_stage_codes,
      disabled_stage_orders,
      disabled_department_slugs,
      laser_machines_count,
      casting_machines_count,
      workers_count,
      max_models_per_batch,
      sets_per_model,
      handover_tolerance_gram
    ) values (
      v_org_id,
      array['PUMICE', 'PUMICE_MACHINE', 'PONZA', 'ZIRCON', 'ZIRCON_MACHINE']::text[],
      array[9, 13]::integer[],
      array['pumice', 'zircon']::text[],
      8, 2, 35, 20, 10, 0.05
    )
    returning * into v_settings;
  end if;

  return jsonb_build_object(
    'organizationId', v_org_id::text,
    'organizationCode', coalesce(v_org.code, 'goldia'),
    'organizationName', coalesce(v_org.name, 'Goldia Jewelry Factory'),
    'disabledStageCodes', coalesce(v_settings.disabled_stage_codes, array[]::text[]),
    'disabledStageOrders', coalesce(v_settings.disabled_stage_orders, array[]::integer[]),
    'disabledDepartmentSlugs', coalesce(v_settings.disabled_department_slugs, array[]::text[]),
    'laserMachinesCount', coalesce(v_settings.laser_machines_count, 8),
    'castingMachinesCount', coalesce(v_settings.casting_machines_count, 2),
    'workersCount', coalesce(v_settings.workers_count, 35),
    'maxModelsPerBatch', coalesce(v_settings.max_models_per_batch, 20),
    'setsPerModel', coalesce(v_settings.sets_per_model, 10),
    'handoverToleranceGram', coalesce(v_settings.handover_tolerance_gram, 0.05)
  );
end;
$$;

revoke all on function public.rpc_get_factory_settings(uuid) from public, anon;
grant execute on function public.rpc_get_factory_settings(uuid) to authenticated, service_role;

;
reset all;
delete from supabase_migrations.schema_migrations where version = '20260101000075';
